;&lt;td&gt;4 &lt;/td&gt;&lt;td&gt;2&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;18 &lt;/td&gt;&lt;td&gt;+13/+8/+3 &lt;/td&gt;&lt;td&gt;+11 &lt;/td&gt;&lt;td&gt;+11 &lt;/td&gt;&lt;td&gt;+6&lt;/td&gt;&lt;td CLASS=&quot;gauche&quot;&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Alchimiste.html#ALCHIMIEINSTANTANEE&quot; title=&quot;L&amp;#39;alchimiste&quot;&gt;Alchimie instantan&#233;e&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Alchimiste.html#DECOUVERTES&quot; title=&quot;L&amp;#39;alchimiste&quot;&gt;d&#233;couverte&lt;/a&gt;&lt;/td&gt;&lt;td&gt;5 &lt;/td&gt;&lt;td&gt;5 &lt;/td&gt;&lt;td&gt;5 &lt;/td&gt;&lt;td&gt;5 &lt;/td&gt;&lt;td&gt;4 &lt;/td&gt;&lt;td&gt;3&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;19 &lt;/td&gt;&lt;td&gt;+14/+9/+4 &lt;/td&gt;&lt;td&gt;+11 &lt;/td&gt;&lt;td&gt;+11 &lt;/td&gt;&lt;td&gt;+6&lt;/td&gt;&lt;td CLASS=&quot;gauche&quot;&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Alchimiste.html#BOMBES&quot; title=&quot;L&amp;#39;alchimiste&quot;&gt;Bombes&lt;/a&gt; 10d6&lt;/td&gt;&lt;td&gt;5 &lt;/td&gt;&lt;td&gt;5 &lt;/td&gt;&lt;td&gt;5 &lt;/td&gt;&lt;td&gt;5 &lt;/td&gt;&lt;td&gt;5 &lt;/td&gt;&lt;td&gt;4&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;20 &lt;/td&gt;&lt;td&gt;+15/+10/+5 &lt;/td&gt;&lt;td&gt;+12 &lt;/td&gt;&lt;td&gt;+12 &lt;/td&gt;&lt;td&gt;+6&lt;/td&gt;&lt;td CLASS=&quot;gauche&quot;&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Alchimiste.html#GRANDESDECOUVERTES&quot; title=&quot;L&amp;#39;alchimiste&quot;&gt;Grande d&#233;couverte&lt;/a&gt;&lt;/td&gt;&lt;td&gt;5 &lt;/td&gt;&lt;td&gt;5 &lt;/td&gt;&lt;td&gt;5 &lt;/td&gt;&lt;td&gt;5 &lt;/td&gt;&lt;td&gt;5 &lt;/td&gt;&lt;td&gt;5&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;br /&gt;&lt;b&gt;R&#244;le.&lt;/b&gt; L’exub&#233;rance (ou, d’apr&#232;s certains, la dangereuse t&#233;m&#233;rit&#233;) de l’alchimiste n’adoucit en rien sa r&#233;putation de perfectionniste en mati&#232;re de fabrication d’extraits et de potions magiques. Il les impr&#232;gne de la magie qu’il puise dans sa propre aura et utilise son corps comme sujet d’exp&#233;rimentation. Et sa passion enjou&#233;e pour la cr&#233;ation de bombes et la d&#233;couverte de nouveaux poisons et m&#233;thodes d’application n’arrange rien. Si ces caract&#233;ristiques repr&#233;sentent un handicap et un risque pour la plupart des organisations civilis&#233;es et des institutions d’&#233;tudes sup&#233;rieures, elles conviennent plut&#244;t bien &#224; la majorit&#233; des groupes d’aventuriers.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Alignement.&lt;/b&gt; Tous.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;D&#233;s de vie.&lt;/b&gt; d8&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Argent de d&#233;part.&lt;/b&gt; 3d6 x 10 po (moyenne 105 po).&lt;br /&gt;&lt;br /&gt;&lt;h2 class=&quot;separator&quot;&gt; Comp&#233;tences de classe &lt;a class=&quot;headeranchor&quot; id=&quot;Comp&#233;tences_de_classe_15&quot; href=&quot;#Comp&#233;tences_de_classe_15&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;Voici les comp&#233;tences de classe de l’alchimiste : &lt;a class=&quot;pagelink&quot; href=&quot;Artisanat.html&quot; title=&quot;Artisanat&quot;&gt;Artisanat&lt;/a&gt; (tous) (Int), &lt;a class=&quot;pagelink&quot; href=&quot;Art-De-La-Magie.html&quot; title=&quot;Art de la magie&quot;&gt;Art de la magie&lt;/a&gt; (Int), &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (myst&#232;res) (Int), &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (nature) (Int), &lt;a class=&quot;pagelink&quot; href=&quot;Escamotage.html&quot; title=&quot;Escamotage&quot;&gt;Escamotage&lt;/a&gt; (Dex), &lt;a class=&quot;pagelink&quot; href=&quot;Estimation.html&quot; title=&quot;Estimation&quot;&gt;Estimation&lt;/a&gt; (Int), &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt; (Sag), &lt;a class=&quot;pagelink&quot; href=&quot;Premiers-Secours.html&quot; title=&quot;Premiers secours&quot;&gt;Premiers secours&lt;/a&gt; (Sag), &lt;a class=&quot;pagelink&quot; href=&quot;Profession.html&quot; title=&quot;Profession&quot;&gt;Profession&lt;/a&gt; (Sag), &lt;a class=&quot;pagelink&quot; href=&quot;Sabotage.html&quot; title=&quot;Sabotage&quot;&gt;Sabotage&lt;/a&gt; (Dex), &lt;a class=&quot;pagelink&quot; href=&quot;Survie.html&quot; title=&quot;Survie&quot;&gt;Survie&lt;/a&gt; (Sag), &lt;a class=&quot;pagelink&quot; href=&quot;Utilisation-Dobjets-Magiques.html&quot; title=&quot;Utilisation d&amp;#39;objets magiques&quot;&gt;Utilisation d’objets magiques&lt;/a&gt; (Cha), &lt;a class=&quot;pagelink&quot; href=&quot;Vol.html&quot; title=&quot;Vol&quot;&gt;Vol&lt;/a&gt; (Dex).&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Rangs de comp&#233;tence par niveau.&lt;/b&gt; 4 + modificateur d’&lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Intelligence.html&quot; title=&quot;L&amp;#39;Intelligence&quot;&gt;Intelligence&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;IMG SRC=&quot;/wiki/public/upload/Illustrations/PNJ/Damiel.jpg&quot; WIDTH=&quot;30%&quot; STYLE=&quot;float: right; background-color: white; padding: 0 0 5px 5px;&quot;/&gt;
&lt;h2 class=&quot;separator&quot;&gt; Descriptif de la classe &lt;a class=&quot;headeranchor&quot; id=&quot;Descriptif_de_la_classe_16&quot; href=&quot;#Descriptif_de_la_classe_16&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;Voici les caract&#233;ristiques de la classe d’alchimiste.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt; Armes et armures &lt;a class=&quot;headeranchor&quot; id=&quot;Armes_et_armures_0&quot; href=&quot;#Armes_et_armures_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;L’alchimiste est capable de manier toutes les &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques-Des-Armes#Armecourante.html&quot; title=&quot;armes courantes&quot;&gt;armes courantes&lt;/a&gt; et des &lt;a class=&quot;pagelink&quot; href=&quot;Alchimiste.html#BOMBES&quot; title=&quot;L&amp;#39;alchimiste&quot;&gt;bombes&lt;/a&gt;. Il est form&#233; au port des armures l&#233;g&#232;res mais pas &#224; celui des boucliers.&lt;br /&gt;&lt;br /&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;ALCHIMIE&quot; href=&quot;#ALCHIMIE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt; Alchimie (Sur) &lt;a class=&quot;headeranchor&quot; id=&quot;Alchimie_Sur_1&quot; href=&quot;#Alchimie_Sur_1&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;&lt;div style=&quot;float:right; padding-left: 6px&quot;&gt;
&lt;table&gt;
&lt;tr style=&quot;vertical-align:bottom&quot;&gt;
&lt;td style=&quot;display:none; background-color: #f3efe2; border: 1px solid #4b3124; padding: 2px; text-align: left&quot;&gt;
&lt;table&gt;&lt;tr style=&quot;vertical-align: top&quot;&gt;&lt;td&gt;
&lt;b&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Faq--Manuel-Des-Joueurs---R&#232;gles-Avanc&#233;es.html#1&quot; title=&quot;FAQ du Manuel des joueurs - R&#232;gles avanc&#233;es&quot;&gt;→&lt;/a&gt; Alchimiste : Dans le cadre des capacit&#233;s de classes de l&#39;alchimiste, les poisons sont-ils consid&#233;r&#233;s comme des objets alchimiques ?&lt;/i&gt;&lt;/b&gt;&lt;br /&gt;&lt;br /&gt;Oui. &lt;i&gt;(Retour &#224; la &lt;u&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Alchimiste.html#ALCHIMIE&quot; title=&quot;L&amp;#39;alchimiste&quot;&gt;capacit&#233;&lt;/a&gt;&lt;/u&gt;)&lt;/i&gt;
&lt;hr&gt;
&lt;b&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Faq--Manuel-Des-Joueurs---R&#232;gles-Avanc&#233;es.html#2&quot; title=&quot;FAQ du Manuel des joueurs - R&#232;gles avanc&#233;es&quot;&gt;→&lt;/a&gt; Alchimiste : Quel type d&#39;action est n&#233;cessaire &#224; l&#39;utilisation d&#39;un extrait, d&#39;un mutag&#232;ne ou d&#39;un lancer de bombe ?&lt;/i&gt;&lt;/b&gt;&lt;br /&gt;&lt;br /&gt;Utiliser un extrait, un mutag&#232;ne ou lancer une bombe n&#233;cessite une action simple. Cette action inclut la r&#233;cup&#233;ration des mat&#233;riaux n&#233;cessaires dans la &lt;u&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Alchimiste.html#ALCHIMIE&quot; title=&quot;L&amp;#39;alchimiste&quot;&gt;r&#233;serve de l&#39;alchimiste&lt;/a&gt;&lt;/u&gt;, de la m&#234;me fa&#231;on que r&#233;cup&#233;rer les composantes mat&#233;rielles est compris dans le fait de lancer un sort.
&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/td&gt;
&lt;td&gt;&lt;img style=&quot;width:50px; cursor:pointer&quot; src=&quot;/wiki/public/upload/Illustrations/Wiki/faqbase1.png&quot; title=&quot;Cliquez pour afficher/cacher une FAQ officielle relative &#224; ce texte&quot; alt=&quot;Cliquez pour afficher/cacher l&#39;information&quot; onclick=&quot;
